int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, sx, sy, dx, dy;
    long long t;
    if (!(cin >> n >> sx >> sy >> dx >> dy >> t)) return 0;

    auto modn = [&](long long a) -> long long {
        a %= n;
        if (a < 0) a += n;
        return a;
    };

    long long x = sx, y = sy;
    long long S = sx + sy; // initial sum x+y
    long long k = S;       // bushes eaten at step 1
    dx += k;
    dy += k;

    long long A = 2;       // coefficient for t^2
    long long B = S;       // coefficient for t

    long long t_mod = t % (2 * n);
    long long t_div = t / (2 * n);

    long long two_n = 2 * n;

    auto compute_pos = [&](long long tt) {
        long long tt_mod = tt % two_n;
        long long tt_div = tt / two_n;

        long long A_mod = modn(A);
        long long B_mod = modn(B);

        long long tt_mod_modn = modn(tt_mod);
        long long tt_mod_sq_modn = (tt_mod_modn * tt_mod_modn) % n;

        long long sum_mod = ( (A_mod * tt_mod_sq_modn) % n + (B_mod * tt_mod_modn) % n ) % n;

        long long dx_mod = modn(dx);
        long long dy_mod = modn(dy);

        long long x_final = modn(sx + dx_mod * tt_mod + sum_mod);
        long long y_final = modn(sy + dy_mod * tt_mod + sum_mod);

        long long x_cycle = modn(dx_mod * two_n + A_mod * (two_n % n) * (two_n % n) + B_mod * (two_n % n));
        long long y_cycle = x_cycle; // same increment

        x_final = modn(x_final + x_cycle * tt_div);
        y_final = modn(y_final + y_cycle * tt_div);

        return pair<long long, long long>(x_final == 0 ? n : x_final, y_final == 0 ? n : y_final);
    };

    auto res = compute_pos(t);
    cout << res.first << " " << res.second << "\n";
    return 0;
}

