int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, sx, sy, dx, dy;
    long long t;
    if (!(cin >> n >> sx >> sy >> dx >> dy >> t)) return 0;

    auto modn = [&](long long a) -> long long {
        a %= n;
        if (a < 0) a += n;
        return a;
    };

    long long x = sx, y = sy;
    long long S = sx + sy; // sum of coordinates

    // Precompute coefficients for S_k and dx_k, dy_k
    // S_k = A*k^2 + B*k + C
    long long A = 1;
    long long B = 2 * S + 1;
    long long C = S;

    // dx_k = dx + S*k + (k*(k-1))/2
    // dy_k = dy + S*k + (k*(k-1))/2

    auto get_S = [&](long long k) -> long long {
        __int128 kk = k;
        __int128 res = (__int128)A * kk * kk + (__int128)B * kk + C;
        long long r = (long long)(res % n);
        if (r < 0) r += n;
        return r;
    };

    auto get_dx = [&](long long k) -> long long {
        __int128 kk = k;
        __int128 term = kk * (kk - 1) / 2;
        __int128 res = (__int128)dx + (__int128)S * kk + term;
        long long r = (long long)(res % n);
        if (r < 0) r += n;
        return r;
    };

    auto get_dy = [&](long long k) -> long long {
        __int128 kk = k;
        __int128 term = kk * (kk - 1) / 2;
        __int128 res = (__int128)dy + (__int128)S * kk + term;
        long long r = (long long)(res % n);
        if (r < 0) r += n;
        return r;
    };

    long long curx = sx, cury = sy;
    long long curS = S;
    long long curdx = modn(dx), curdy = modn(dy);

    long long steps = 0;
    const long long MAX_SIM = 2000000;
    map<tuple<long long,long long,long long,long long,long long>, long long> seen;

    while (steps < t) {
        auto state = make_tuple(curx, cury, curdx, curdy, curS % n);
        auto it = seen.find(state);
        if (it != seen.end()) {
            long long first = it->second;
            long long cycle_len = steps - first;
            if (cycle_len > 0) {
                long long remaining = t - steps;
                long long skip = remaining / cycle_len;
                if (skip > 0) {
                    steps += skip * cycle_len;
                    continue;
                }
            }
        } else if ((long long)seen.size() < MAX_SIM) {
            seen[state] = steps;
        }

        if (steps >= t) break;

        long long k = curS;
        curdx = modn(curdx + k);
        curdy = modn(curdy + k);

        curx = modn(curx + curdx - 1) + 1;
        cury = modn(cury + curdy - 1) + 1;

        curS = curx + cury + steps + 1; // +1 for new bushes each second

        steps++;
    }

    cout << curx << " " << cury << "\n";
    return 0;
}

