int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, sx, sy, dx, dy;
    long long t;
    if (!(cin >> n >> sx >> sy >> dx >> dy >> t)) return 0;

    auto modn = [&](long long v) {
        v %= n;
        if (v < 0) v += n;
        return v;
    };

    long long x = sx, y = sy;

    if (t == 0) {
        cout << x << " " << y << "\n";
        return 0;
    }

    long long S = sx + sy;
    long long A = dx + dy;
    long long B = 2; // coefficient of i in S_i

    long long T = t;
    long long i = 0;

    while (T > 0) {
        long long S_mod = modn(S);
        long long B_mod = modn(B);

        long long step;
        if (B_mod == 0) {
            if (S_mod == 0) step = T;
            else step = 0;
        } else {
            long long g = std::gcd(B_mod, n);
            if (S_mod % g != 0) {
                step = 0;
            } else {
                long long n1 = n / g;
                long long B1 = B_mod / g;
                long long S1 = S_mod / g;
                long long invB1;
                {
                    long long a = B1, m = n1;
                    long long u = 1, v = 0;
                    while (m) {
                        long long t2 = a / m;
                        a -= t2 * m; swap(a, m);
                        u -= t2 * v; swap(u, v);
                    }
                    invB1 = (u % n1 + n1) % n1;
                }
                long long i0 = (invB1 * S1) % n1;
                long long maxStep = (T < n1 ? T : n1);
                if (i0 == 0) step = 0;
                else step = (i0 <= maxStep ? i0 : 0);
            }
        }

        if (step == 0) {
            long long k = S + i * B;
            dx += k;
            dy += k;
            x = modn(x + dx - 1) + 1;
            y = modn(y + dy - 1) + 1;
            S += A + 2 * i + 1;
            A += 2 * k;
            B += 2;
            i++;
            T--;
        } else {
            long long k_start = S + i * B;
            long long A_new = A + 2 * k_start * step + B * step * (step - 1);
            long long B_new = B + 2 * step;
            long long S_new = S + A * step + B * step * (step - 1) / 2 + step * step;
            long long dx_new = dx + k_start * step + B * step * (step - 1) / 2;
            long long dy_new = dy + k_start * step + B * step * (step - 1) / 2;

            long long delta_x = dx * step + k_start * step * (step + 1) / 2 + B * step * (step - 1) * (step + 1) / 6;
            long long delta_y = delta_x;

            x = modn(x + delta_x - 1) + 1;
            y = modn(y + delta_y - 1) + 1;

            dx = dx_new;
            dy = dy_new;
            S = S_new;
            A = A_new;
            B = B_new;
            i += step;
            T -= step;
        }
    }

    cout << x << " " << y << "\n";
    return 0;
}

