int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, sx, sy, dx, dy;
    long long t;
    if (!(cin >> n >> sx >> sy >> dx >> dy >> t)) return 0;

    auto modn = [&](long long v) {
        v %= n;
        if (v < 0) v += n;
        return v;
    };

    long long x = sx, y = sy;
    long long S = sx + sy;
    long long dx0 = dx, dy0 = dy;

    long long steps = min(t, 4 * n + 5);
    for (long long i = 0; i < steps; ++i) {
        long long k = S + i;
        dx += k;
        dy += k;
        x = modn(x + dx - 1) + 1;
        y = modn(y + dy - 1) + 1;
        S += 2;
    }

    if (t > steps) {
        long long rem = t - steps;
        long long dx1 = dx, dy1 = dy;
        long long x1 = x, y1 = y;
        long long S1 = S;

        long long period = 0;
        long long maxCheck = min(rem, 4 * n + 5);
        for (long long i = 1; i <= maxCheck; ++i) {
            long long k = S1 + (i - 1);
            dx1 += k;
            dy1 += k;
            x1 = modn(x1 + dx1 - 1) + 1;
            y1 = modn(y1 + dy1 - 1) + 1;
            S1 += 2;
            if (x1 == x && y1 == y && dx1 == dx && dy1 == dy) {
                period = i;
                break;
            }
        }

        if (period == 0) {
            period = maxCheck;
        }

        long long cycles = rem / period;
        long long extra = rem % period;

        long long delta_dx = dx1 - dx;
        long long delta_dy = dy1 - dy;
        long long delta_S = S1 - S;

        dx += delta_dx * cycles;
        dy += delta_dy * cycles;
        S += delta_S * cycles;

        for (long long i = 0; i < extra; ++i) {
            long long k = S + i;
            dx += k;
            dy += k;
            x = modn(x + dx - 1) + 1;
            y = modn(y + dy - 1) + 1;
            S += 2;
        }
    }

    cout << x << " " << y << '\n';
    return 0;
}

