int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, sx, sy, dx, dy;
    long long t;
    if (!(cin >> n >> sx >> sy >> dx >> dy >> t)) return 0;

    auto modn = [&](long long v) {
        v %= n;
        if (v < 0) v += n;
        return v;
    };

    long long x = sx, y = sy;
    long long S = sx + sy; // initial bushes at start cell

    // dx, dy can be negative; we will keep them as long long
    // Precompute constants for formulas
    long long dx0 = dx, dy0 = dy;

    // We will simulate until we find a cycle or reach t
    // State: (x,y,dx,dy) but dx,dy grow fast; we use (x,y,S mod n) as key
    // Because position depends on S only modulo n.
    unordered_map<long long, pair<long long,long long>> seen; // key -> (time, S)
    // key = (x-1)*n + (y-1) with Smod encoded separately; but to keep map small, we use (x,y,Smod)
    struct State {
        long long x,y,smod;
    };
    struct KeyHash {
        size_t operator()(const State& st) const {
            return ((st.x*1000003ULL + st.y)*1000003ULL + st.smod);
        }
    };
    struct KeyEq {
        bool operator()(const State& a, const State& b) const {
            return a.x==b.x && a.y==b.y && a.smod==b.smod;
        }
    };
    unordered_map<State, pair<long long,long long>, KeyHash, KeyEq> mp;
    mp.reserve(100000);
    mp.max_load_factor(0.7);

    long long time = 0;
    while (time < t) {
        long long smod = ((S % n) + n) % n;
        State st{ x, y, smod };
        auto it = mp.find(st);
        if (it != mp.end()) {
            long long t0 = it->second.first;
            long long S0 = it->second.second;
            long long cycle_len = time - t0;
            long long dS = S - S0;
            if (cycle_len > 0) {
                long long remaining = t - time;
                long long cycles = remaining / cycle_len;
                if (cycles > 0) {
                    time += cycles * cycle_len;
                    S += cycles * dS;
                }
            }
            if (time >= t) break;
        } else {
            mp[st] = {time, S};
        }

        // bushes at current cell at this second:
        long long k = S; // x + y + time
        dx += k;
        dy += k;

        // move
        x = modn(x + dx - 1) + 1;
        y = modn(y + dy - 1) + 1;

        time++;
        S = x + y + time;
    }

    cout << x << " " << y << "\n";
    return 0;
}

